def countGoodIntegersOnPath(l, r, directions):
    # Convert the path into flat positions (0..15) in the 4x4 row-major layout
    row = col = 0
    path = [0]
    for ch in directions:
        if ch == 'D':
            row += 1
        else:
            col += 1
        path.append(row * 4 + col)
    on_path = set(path)

    def count_up_to(x):
        # Number of good integers in [0, x], where x is viewed as a 16-digit string
        if x < 0:
            return 0
        digits = [int(ch) for ch in str(x).zfill(16)]
        memo = {}

        def go(pos, tight, last):
            # pos: next cell to fill, tight: prefix still equals x's prefix,
            # last: digit at the previous path cell
            if pos == 16:
                return 1
            key = (pos, tight, last)
            if key in memo:
                return memo[key]
            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                if pos in on_path:
                    # Along the path the digits must not decrease
                    if d < last:
                        continue
                    nxt_last = d
                else:
                    # Cells off the path are unconstrained
                    nxt_last = last
                total += go(pos + 1, tight and d == limit, nxt_last)
            memo[key] = total
            return total

        return go(0, True, 0)

    # Good integers in [l, r] = good up to r minus good up to l - 1
    return count_up_to(r) - count_up_to(l - 1)
